import{_ as t,o as a,c as s,a8 as i}from"./chunks/framework.DB1tY2mn.js";const g=JSON.parse('{"title":"Untitled string in Mermaid Config Schema","description":"","frontmatter":{"editLink":"https://github.com/mermaid-js/mermaid/edit/develop/packages/mermaid/src/schemas/config.schema.yaml","head":[["link",{"rel":"canonical","href":"https://mermaid.ai/open-source/config/schema-docs/config-properties-elk-properties-preset.html"}]]},"headers":[],"relativePath":"config/schema-docs/config-properties-elk-properties-preset.md","filePath":"config/schema-docs/config-properties-elk-properties-preset.md"}'),o={name:"config/schema-docs/config-properties-elk-properties-preset.md"};function l(r,e,n,d,c,h){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="untitled-string-in-mermaid-config-schema" tabindex="-1">Untitled string in Mermaid Config Schema <a class="header-anchor" href="#untitled-string-in-mermaid-config-schema" aria-label="Permalink to &quot;Untitled string in Mermaid Config Schema&quot;">​</a></h1><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://mermaid.js.org/schemas/config.schema.json#/properties/elk/properties/preset</span></span></code></pre></div><p>Named combination of the three options that decide where nodes end up: layering strategy, node placement strategy and cycle breaking strategy. They belong to different phases of the layout, so a preset is simply a named triple rather than a mode with behaviour of its own.</p><p><code>default</code> — network simplex layering and placement with depth-first cycle breaking at the top level, and Brandes-Koepf placement inside subgraphs. Depth-first breaking gives shorter back edges on graphs that loop.</p><p><code>legacy</code> — what shipped before presets existed: Brandes-Koepf placement, which straightens long edges at the cost of that alignment, with ELK&#39;s own greedy cycle breaking. Reproduces the rendering of earlier versions rather than the defaults their schema advertised.</p><p><code>modelOrder</code> — as <code>default</code>, but breaks cycles by greedy model order, which disturbs declaration order least at the cost of longer back edges. This is the combination <code>default</code> named previously.</p><p><code>depthFirst</code> — a name for what <code>default</code> already is, for diagrams that would rather say depth-first than rely on the default.</p><p>Setting <code>layeringStrategy</code>, <code>nodePlacementStrategy</code> or <code>cycleBreakingStrategy</code> explicitly overrides the preset for that one option; the rest of the preset still applies.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Abstract</th><th style="text-align:left;">Extensible</th><th style="text-align:left;">Status</th><th style="text-align:left;">Identifiable</th><th style="text-align:left;">Custom Properties</th><th style="text-align:left;">Additional Properties</th><th style="text-align:left;">Access Restrictions</th><th style="text-align:left;">Defined In</th></tr></thead><tbody><tr><td style="text-align:left;">Can be instantiated</td><td style="text-align:left;">No</td><td style="text-align:left;">Unknown status</td><td style="text-align:left;">Unknown identifiability</td><td style="text-align:left;">Forbidden</td><td style="text-align:left;">Allowed</td><td style="text-align:left;">none</td><td style="text-align:left;"><a href="/dochub/mermaid/schemas/config.schema.json" title="open original schema">config.schema.json*</a></td></tr></tbody></table><h2 id="preset-type" tabindex="-1">preset Type <a class="header-anchor" href="#preset-type" aria-label="Permalink to &quot;preset Type&quot;">​</a></h2><p><code>string</code></p><h2 id="preset-constraints" tabindex="-1">preset Constraints <a class="header-anchor" href="#preset-constraints" aria-label="Permalink to &quot;preset Constraints&quot;">​</a></h2><p><strong>enum</strong>: the value of this property must be equal to one of the following values:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Value</th><th style="text-align:left;">Explanation</th></tr></thead><tbody><tr><td style="text-align:left;"><code>&quot;default&quot;</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>&quot;legacy&quot;</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>&quot;modelOrder&quot;</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>&quot;depthFirst&quot;</code></td><td style="text-align:left;"></td></tr></tbody></table><h2 id="preset-default-value" tabindex="-1">preset Default Value <a class="header-anchor" href="#preset-default-value" aria-label="Permalink to &quot;preset Default Value&quot;">​</a></h2><p>The default value is:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;default&quot;</span></span></code></pre></div>',17)])])}const f=t(o,[["render",l]]);export{g as __pageData,f as default};
